import json
from flask import Flask, request, redirect, jsonify

app = Flask(__name__)

# Path to the JSON file
DATA_FILE = 'mappings.json'

# Load existing data
try:
    with open(DATA_FILE, 'r') as f:
        data = json.load(f)
except (FileNotFoundError, json.JSONDecodeError):
    data = {'mappings': {}, 'stats': {}}

mappings = data['mappings']
stats = data['stats']

def generate_short_code():
    import random
    import string
    return ''.join(random.choices(string.ascii_letters + string.digits, k=6))

@app.route('/shorten', methods=['POST'])
def shorten():
    url = request.json.get('url')
    if not url:
        return jsonify({'error': 'Missing URL'}), 400
    short_code = generate_short_code()
    while short_code in mappings:
        short_code = generate_short_code()
    mappings[short_code] = url
    stats[short_code] = {'clicks': 0}
    # Write back to file
    data['mappings'] = mappings
    data['stats'] = stats
    with open(DATA_FILE, 'w') as f:
        json.dump(data, f)
    return jsonify({'short_code': short_code})

@app.route('/<short_code>', methods=['GET'])
def redirect_to_url(short_code):
    if short_code in mappings:
        stats[short_code]['clicks'] += 1
        # Write back to file
        data['mappings'] = mappings
        data['stats'] = stats
        with open(DATA_FILE, 'w') as f:
            json.dump(data, f)
        return redirect(mappings[short_code])
    else:
        return '404 Not Found', 404

@app.route('/stats/<short_code>', methods=['GET'])
def get_stats(short_code):
    if short_code in stats:
        return jsonify(stats[short_code])
    else:
        return '404 Not Found', 404

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)

const express = require('express');
const fs = require('fs');
const app = express();
const PORT = 5000;

// Path to the JSON file
const DATA_FILE = 'mappings.json';

// Load existing data
let data = {
  mappings: {},
  stats: {}
};

try {
  const fileData = fs.readFileSync(DATA_FILE, 'utf-8');
  data = JSON.parse(fileData);
} catch (err) {
  console.log('No existing data found, using default structure');
}

const { mappings, stats } = data;

// Generate short code
function generateShortCode() {
  const chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let code = '';
  for (let i = 0; i < 6; i++) {
    code += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return code;
}

// Route to shorten URL
app.post('/shorten', express.json(), (req, res) => {
  const { url } = req.body;
  if (!url) {
    return res.status(400).json({ error: 'Missing URL' });
  }

  let shortCode;
  do {
    shortCode = generateShortCode();
  } while (mappings[shortCode]);

  mappings[shortCode] = url;
  stats[shortCode] = { clicks: 0 };

  // Write back to file
  fs.writeFileSync(DATA_FILE, JSON.stringify({ mappings, stats }));

  res.json({ shortCode });
});

// Route to redirect
app.get('/:shortCode', (req, res) => {
  const { shortCode } = req.params;
  if (mappings[shortCode]) {
    stats[shortCode].clicks++;
    fs.writeFileSync(DATA_FILE, JSON.stringify({ mappings, stats }));
    res.redirect(mappings[shortCode]);
  } else {
    res.status(404).send('404 Not Found');
  }
});

// Route to get stats
app.get('/stats/:shortCode', (req, res) => {
  const { shortCode } = req.params;
  if (stats[shortCode]) {
    res.json(stats[shortCode]);
  } else {
    res.status(404).send('404 Not Found');
  }
});

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
